        node.next = self.head.next
        self.head.next.prev = node
        self.head.next = node

    def _remove_node(self, node):
        node.prev.next = node.next
        node.next.prev = node.prev

    def _move_to_head(self, node):
        self._remove_node(node)
        self._add_to_head(node)

    def _pop_tail(self):
        node = self.tail.prev
        self._remove_node(node)
        return node

    def get(self, key) -> int:
        if key in self.cache:
            node = self.cache[key]
            self._move_to_head(node)
            return node.value
        return -1

    def put(self, key, value) -> None:
        if key in self.cache:
            node = self.cache[key]
            node.value = value
            self._move_to_head(node)
        else:
            new_node = Node(key, value)
            self.cache[key] = new_node
            self._add_to_head(new_node)
            if len(self.cache) > self.capacity:
                tail_node = self._pop_tail()
                del self.cache[tail_node.key]

def merge_intervals(intervals: list[list[int]]) -> list[list[int]]:
    if not intervals:
        return []

    intervals.sort(key=lambda x: x[0])
    merged = [intervals[0]]

    for curr in intervals[1:]:
        if curr[0] <= merged[-1][1]:
            merged[-1][1] = max(merged[-1][1], curr[1])
        else:
            merged.append(curr)

    return merged

def merge_intervals(intervals: list[list[int]]) -> list[list[int]]:
    if not intervals:
        return []

    sorted_intervals = sorted(intervals, key=lambda x: x[0])
    merged = [sorted_intervals[0]]

    for current in sorted_intervals[1:]:
        if current[0] <= merged[-1][1]:
            merged[-1][1] = max(merged[-1][1], current[1])
        else:
            merged.append(current)

    return merged

def edit_distance(a: str, b: str) -> int:
    m, n = len(a), len(b)
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(m + 1):
        dp[i][0] = i
    for j in range(n + 1):
        dp[0][j] = j
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            cost = 0 if a[i - 1] == b[j - 1] else 1
            dp[i][j] = min(dp[i - 1][j] + 1, dp[i][j - 1] + 1, dp[i - 1][j - 1] + cost)
    return dp[m][n]

def edit_distance(a: str, b: str) -> int:
    m, n = len(a), len(b)
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(m + 1):
        dp[i][0] = i
    for j in range(n + 1):
        dp[0][j] = j

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if a[i-1] == b[j-1]:
                dp[i][j] = dp[i-1][j-1]
            else:
                dp[i][j] = 1 + min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1])

    return dp[m][n]

def flatten(obj, sep='.'):
    result = {}

    def _flatten(current, prefix):
        if isinstance(current, dict):
            for k, v in current.items():
                new_prefix = f"{prefix}{sep}{k}" if prefix else k
                _flatten(v, new_prefix)
        elif isinstance(current, list):
            for i, v in enumerate(current):
                new_prefix = f"{prefix}{sep}{str(i)}" if prefix else str(i)
                _flatten(v, new_prefix)
        else:
            result[prefix] = current

    _flatten(obj, '')
    return result

def flatten(obj, sep='.'):
    result = {}
    def _flatten(current, prefix):
        if isinstance(current, dict):
            for k, v in current.items():
                new_prefix = prefix + [str(k)]
                if isinstance(v, (dict, list)):
                    _flatten(v, new_prefix)
                else:
                    result[sep.join(new_prefix)] = v
        elif isinstance(current, list):
            for i, v in enumerate(current):
                new_prefix = prefix + [str(i)]
                if isinstance(v, (dict, list)):
                    _flatten(v, new_prefix)
                else:
                    result[sep.join(new_prefix)] = v

    if isinstance(obj, (dict, list)):
        _flatten(obj, [])
    return result

def compare_versions(v1: str, v2: str) -> int:
    parts1 = list(map(int, v1.split('.')))
    parts2 = list(map(int, v2.split('.')))

    max_len = max(len(parts1), len(parts2))

    for i in range(max_len):
        p1 = parts1[i] if i < len(parts1) else 0
        p2 = parts2[i] if i < len(parts2) else 0

        if p1 < p2:
            return -1
        elif p1 > p2:
            return 1

    return 0

import functools

def retry(times: int, exceptions=(Exception,)):
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            last_exc = None
            for _ in range(times):
                try:
                    return func(*args, **kwargs)
                except exceptions as e:
                    last_exc = e
            raise last_exc
        return wrapper
    return decorator

