import re

def parse_select(sql: str) -> dict:
    pattern = r"^\s*SELECT\s+(.*?)\s+FROM\s+(\S+)(?:\s+WHERE\s+(.*))?\s*$"
    match = re.match(pattern, sql, re.IGNORECASE | re.DOTALL)
    if not match:
        raise ValueError("Invalid SELECT statement")

    columns_str = match.group(1).strip()
    table = match.group(2)
    where_str = match.group(3)

    if columns_str.upper() == "*":
        columns = ["*"]
    else:
        columns = [c.strip() for c in columns_str.split(",") if c.strip()]

    where_val = where_str.strip() if where_str else None
    return {
        "columns": columns,
        "table": table,
        "where": where_val if where_val else None
    }

import re

def parse_select(sql: str) -> dict:
    sql = sql.strip()
    if sql.endswith(';'):
        sql = sql[:-1].strip()

    tokens = re.split(r'\b(SELECT|FROM|WHERE)\b', sql, flags=re.IGNORECASE)
    tokens = [t.strip() for t in tokens if t.strip()]

    if not tokens or tokens[0].upper() != 'SELECT':
        raise ValueError("Invalid SELECT statement")

    columns_str = tokens[1]
    table = tokens[3]
    where = tokens[5] if len(tokens) == 6 else None

    if columns_str == '*':
        columns = ['*']
    else:
        columns = [c.strip() for c in columns_str.split(',')]

    return {'columns': columns, 'table': table, 'where': where}

import heapq

def topo_sort(nodes: list, edges: list[tuple]) -> list:
    adj = {node: [] for node in nodes}
    in_degree = {node: 0 for node in nodes}

    for a, b in edges:
        adj[a].append(b)
        in_degree[b] += 1

    heap = [node for node in nodes if in_degree[node] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        u = heapq.heappop(heap)
        result.append(u)
        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                heapq.heappush(heap, v)

    if len(result) != len(nodes):
        raise ValueError("Cycle detected")

    return result

import heapq

def topo_sort(nodes: list, edges: list[tuple]) -> list:
    in_degree = {node: 0 for node in nodes}
    adj = {node: [] for node in nodes}

    for u, v in edges:
        if u not in adj:
            adj[u] = []
            in_degree[u] = 0
        if v not in adj:
            adj[v] = []
            in_degree[v] = 0
        adj[u].append(v)
        in_degree[v] += 1

    heap = [node for node in nodes if in_degree.get(node, 0) == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        u = heapq.heappop(heap)
        result.append(u)
        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                heapq.heappush(heap, v)

    if len(result) != len(set(nodes)):
        raise ValueError("Cycle detected")

    return result

from collections import deque, defaultdict

def ladder_length(begin: str, end: str, words: list[str]) -> int:
    if len(begin) != len(end):
        return 0

    words_set = set(words)
    if end not in words_set:
        return 0

    word_patterns = defaultdict(list)
    for word in words_set:
        for i in range(len(word)):
            pattern = word[:i] + "*" + word[i+1:]
            word_patterns[pattern].append(word)

    queue = deque([(begin, 1)])
    visited = {begin}

    while queue:
        word, level = queue.popleft()
        if word == end:
            return level

        for i in range(len(word)):
            pattern = word[:i] + "*" + word[i+1:]
            for neighbor in word_patterns[pattern]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append((neighbor, level + 1))

    return 0

