import string

def ladder_length(begin: str, end: str, words: list[str]) -> int:
    word_set = set(words)
    if end not in word_set:
        return 0

    queue = deque([(begin, 1)])
    visited = {begin}

    while queue:
        word, length = queue.popleft()
        if word == end:
            return length

        for i in range(len(word)):
            for char in string.ascii_lowercase:
                new_word = word[:i] + char + word[i+1:]
                if new_word in word_set and new_word not in visited:
                    visited.add(new_word)
                    queue.append((new_word, length + 1))

    return 0

def evaluate(expr: str) -> float:
    s = expr
    n = len(s)
    pos = 0

    def peek():
        nonlocal pos
        return s[pos] if pos < n else None

    def advance():
        nonlocal pos
        pos += 1

    def skip_ws():
        nonlocal pos
        while pos < n and s[pos].isspace():
            pos += 1

    def parse_number():
        nonlocal pos
        start = pos
        has_dot = False
        while pos < n and (s[pos].isdigit() or (s[pos] == '.' and not has_dot)):
            if s[pos] == '.':
                has_dot = True
            pos += 1
        if pos == start:
            raise ValueError(f"Expected number at position {pos}")
        try:
            return float(s[start:pos])
        except ValueError:
            raise ValueError(f"Invalid number '{s[start:pos]}' at position {pos}")

    def parse_factor():
        nonlocal pos
        skip_ws()
        c = peek()
        if c is None:
            raise ValueError("Unexpected end of expression")

        if c == '(':
            advance()
            val = parse_expr()
            skip_ws()
            if peek() != ')':
                raise ValueError("Expected ')'")
            advance()
            return val

        if c == '+' or c == '-':
            sign = -1 if c == '-' else 1
            advance()
            return sign * parse_factor()

        if c.isdigit() or c == '.':
            return parse_number()

        raise ValueError(f"Unexpected character '{c}' at position {pos}")

    def parse_term():
        nonlocal pos
        val = parse_factor()
        while True:
            skip_ws()
            c = peek()
            if c == '*' or c == '/':
                advance()
                right = parse_factor()
                if c == '*':
                    val *= right
                else:
                    if right == 0:
                        raise ValueError("Division by zero")
                    val /= right
            else:
                break
        return val

    def parse_expr():
        nonlocal pos
        val = parse_term()
        while True:
            skip_ws()
            c = peek()
            if c == '+' or c == '-':
                advance()
                right = parse_term()
                if c == '+':
                    val += right
                else:
                    val -= right
            else:
                break
        return val

    result = parse_expr()
    skip_ws()
    if pos < n:
        raise ValueError(f"Unexpected character '{s[pos]}' at position {pos}")
    return result

def evaluate(expr: str) -> float:
    def tokenize(s: str):
        tokens = []
        i, n = 0, len(s)
        while i < n:
            if s[i].isspace():
                i += 1
                continue
            if s[i].isdigit() or s[i] == '.':
                j = i
                has_dot = False
                while j < n and (s[j].isdigit() or s[j] == '.'):
                    if s[j] == '.':
                        if has_dot:
                            raise ValueError("Invalid number format")
                        has_dot = True
                    j += 1
                try:
                    tokens.append(('NUM', float(s[i:j])))
                except ValueError:
                    raise ValueError(f"Invalid number: {s[i:j]}")
                i = j
            elif s[i] in '+-*/':
                tokens.append(('OP', s[i]))
                i += 1
            elif s[i] == '(':
                tokens.append(('LPAREN', '('))
                i += 1
            elif s[i] == ')':
                tokens.append(('RPAREN', ')'))
                i += 1
            else:
                raise ValueError(f"Unexpected character: {s[i]}")
        tokens.append(('EOF',))
        return tokens

    class Parser:
        def __init__(self, tokens):
            self.tokens = tokens
            self.pos = 0

        def current(self):
            return self.tokens[self.pos]

        def consume(self, expected_type=None):
            token = self.current()
            if expected_type and token[0] != expected_type:
                raise ValueError(f"Expected {expected_type}, got {token[0]}")
            self.pos += 1
            return token

        def parse_expr(self):
            left = self.parse_term()
            while self.current()[0] == 'OP' and self.current()[1] in '+-':
                op = self.consume()[1]
                right = self.parse_term()
                if op == '+':
                    left += right
                else:
                    left -= right
            return left

        def parse_term(self):
            left = self.parse_factor()
            while self.current()[0] == 'OP' and self.current()[1] in '*/':
                op = self.consume()[1]
                right = self.parse_factor()
                if op == '*':
                    left *= right
                else:
                    left /= right
            return left

        def parse_factor(self):
            token = self.current()
            if token[0] == 'EOF':
                raise ValueError("Unexpected end of input")
            if token[0] == 'OP' and token[1] in '+-':
                op = self.consume()[1]
                val = self.parse_factor()
                return -val if op == '-' else val
            elif token[0] == 'NUM':
                self.consume()
                return token[1]
            elif token[0] == 'LPAREN':
                self.consume()
                val = self.parse_expr()
                self.consume('RPAREN')
                return val
            else:
                raise ValueError(f"Unexpected token: {token}")

    tokens = tokenize(expr)
    parser = Parser(tokens)
    if parser.current()[0] == 'EOF':
        raise ValueError("Empty expression")
    result = parser.parse_expr()
    if parser.current()[0] != 'EOF':
        raise ValueError("Unexpected tokens after expression")
    return result

def diff(a: list[str], b: list[str]) -> list[tuple[str, str]]:
    m, n = len(a), len(b)
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if a[i-1] == b[j-1]:
                dp[i][j] = dp[i-1][j-1] + 1
            else:
                dp[i][j] = max(dp[i-1][j], dp[i][j-1])

    res = []
    i, j = m, n
    while i > 0 and j > 0:
        if a[i-1] == b[j-1]:
            res.append((' ', a[i-1]))
            i -= 1
            j -= 1
        elif dp[i-1][j] > dp[i][j-1]:
            res.append(('-', a[i-1]))
            i -= 1
        else:
            res.append(('+', b[j-1]))
            j -= 1

    while i > 0:
        res.append(('-', a[i-1]))
        i -= 1
    while j > 0:
        res.append(('+', b[j-1]))
        j -= 1

    return res[::-1]

