class SlidingWindowRateLimiter:
    def __init__(self, max_calls: int, window: float):
        self.max_calls = max_calls
        self.window = window
        self.logs = {}

    def allow(self, key: str, now: float) -> bool:
        if key not in self.logs:
            self.logs[key] = []

        cutoff = now - self.window
        self.logs[key] = [t for t in self.logs[key] if t > cutoff]

        if len(self.logs[key]) < self.max_calls:
            self.logs[key].append(now)
            return True
        return False

from collections import deque

class SlidingWindowRateLimiter:
    def __init__(self, max_calls: int, window: float):
        self.max_calls = max_calls
        self.window = window
        self.logs = {}

    def allow(self, key: str, now: float) -> bool:
        if key not in self.logs:
            self.logs[key] = deque()

        logs = self.logs[key]
        cutoff = now - self.window

        while logs and logs[0] <= cutoff:
            logs.popleft()

        if len(logs) < self.max_calls:
            logs.append(now)
            return True
        return False

def is_match(s: str, p: str) -> bool:
    m, n = len(s), len(p)
    dp = [[False] * (n + 1) for _ in range(m + 1)]
    dp[0][0] = True

    for j in range(1, n + 1):
        if p[j-1] == '*':
            dp[0][j] = dp[0][j-2] if j >= 2 else False

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if p[j-1] == '.' or p[j-1] == s[i-1]:
                dp[i][j] = dp[i-1][j-1]
            elif p[j-1] == '*':
                dp[i][j] = dp[i][j-2] if j >= 2 else False
                if j >= 2 and (p[j-2] == '.' or p[j-2] == s[i-1]):
                    dp[i][j] = dp[i][j] or dp[i-1][j]

    return dp[m][n]

