                dp[i][j] = dp[i-1][j-1]
            elif p[j-1] == '*':
                if j >= 2 and (dp[i][j-2] or (p[j-2] == '.' or p[j-2] == s[i-1]) and dp[i-1][j]):
                    dp[i][j] = True

    return dp[m][n]

class _Parser:
    def __init__(self, text):
        self.text = text
        self.pos = 0

    def peek(self):
        if self.pos < len(self.text):
            return self.text[self.pos]
        return None

    def advance(self):
        ch = self.text[self.pos]
        self.pos += 1
        return ch

    def skip_ws_and_comments(self):
        while self.pos < len(self.text):
            ch = self.text[self.pos]
            if ch in ' \t\n\r':
                self.pos += 1
            elif ch == '/':
                if self.pos + 1 < len(self.text) and self.text[self.pos+1] == '/':
                    self.pos += 2
                    while self.pos < len(self.text) and self.text[self.pos] != '\n':
                        self.pos += 1
                    if self.pos < len(self.text):
                        self.pos += 1
                elif self.pos + 1 < len(self.text) and self.text[self.pos+1] == '*':
                    self.pos += 2
                    while self.pos + 1 < len(self.text):
                        if self.text[self.pos] == '*' and self.text[self.pos+1] == '/':
                            self.pos += 2
                            break
                        self.pos += 1
                    else:
                        raise ValueError("Unterminated block comment")
                else:
                    raise ValueError("Invalid comment syntax")
            else:
                break

    def parse(self):
        self.skip_ws_and_comments()
        if self.pos >= len(self.text):
            raise ValueError("Empty input")
        val = self.parse_value()
        self.skip_ws_and_comments()
        if self.pos < len(self.text):
            raise ValueError("Trailing non-whitespace after top-level value")
        return val

    def parse_value(self):
        self.skip_ws_and_comments()
        ch = self.peek()
        if ch is None:
            raise ValueError("Unexpected end of input")

        if ch == '"':
            return self.parse_string(dq=True)
        elif ch == "'":
            return self.parse_string(dq=False)
        elif ch == '{':
            return self.parse_object()
        elif ch == '[':
            return self.parse_array()
        elif ch == 't':
            return self.parse_literal('true', True)
        elif ch == 'f':
            return self.parse_literal('false', False)
        elif ch == 'n':
            return self.parse_literal('null', None)
        elif ch == '-' or ch.isdigit():
            return self.parse_number()
        else:
            raise ValueError(f"Unexpected character: {ch}")

    def parse_string(self, dq=True):
        quote = '"' if dq else "'"
        self.expect(quote)
        chars = []
        while True:
            if self.pos >= len(self.text):
                raise ValueError("Unterminated string")
            ch = self.advance()
            if ch == quote:
                break
            elif ch == '\\':
                if self.pos >= len(self.text):
                    raise ValueError("Unterminated escape")
                esc = self.advance()
                if esc == 'n':
                    chars.append('\n')
                elif esc == 't':
                    chars.append('\t')
                elif esc == '\\':
                    chars.append('\\')
                elif esc == '"':
                    chars.append('"')
                elif esc == "'":
                    chars.append("'")
                elif esc == '/':
                    chars.append('/')
                elif esc == 'u':
                    hex_str = ""
                    for _ in range(4):
                        if self.pos >= len(self.text):
                            raise ValueError("Unterminated unicode escape")
                        h = self.advance()
                        if h not in '0123456789abcdefABCDEF':
                            raise ValueError("Invalid unicode escape")
                        hex_str += h
                    chars.append(chr(int(hex_str, 16)))
                else:
                    raise ValueError(f"Invalid escape: \\{esc}")
            else:
                chars.append(ch)
        return ''.join(chars)

    def parse_literal(self, expected, value):
        for ch in expected:
            if self.advance() != ch:
                raise ValueError(f"Expected '{expected}'")
        return value

    def parse_number(self):
        num_str = []
        if self.peek() == '-':
            num_str.append(self.advance())
        if not self.peek() or not self.peek().isdigit():
            raise ValueError("Expected digit")
        while self.peek() and self.peek().isdigit():
            num_str.append(self.advance())
        if self.peek() == '.':
            num_str.append(self.advance())
            if not self.peek() or not self.peek().isdigit():
                raise ValueError("Expected digit after decimal point")
            while self.peek() and self.peek().isdigit():
                num_str.append(self.advance())
        if self.peek() in ('e', 'E'):
            num_str.append(self.advance())
            if self.peek() in ('+', '-'):
                num_str.append(self.advance())
            if not self.peek() or not self.peek().isdigit():
                raise ValueError("Expected digit in exponent")
            while self.peek() and self.peek().isdigit():
                num_str.append(self.advance())

        s = ''.join(num_str)
        if '.' in s or 'e' in s or 'E' in s:
            return float(s)
        else:
            return int(s)

    def parse_object(self):
        self.expect('{')
        obj = {}
        self.skip_ws_and_comments()
        if self.peek() == '}':
            self.advance()
            return obj

        while True:
            self.skip_ws_and_comments()
            key = None
            if self.peek() == '"':
                key = self.parse_string(dq=True)
            elif self.peek() == "'":
                key = self.parse_string(dq=False)
            elif self.peek() and (self.peek().isalpha() or self.peek() == '_'):
                start = self.pos
                while self.pos < len(self.text) and (self.text[self.pos].isalnum() or self.text[self.pos] == '_'):
                    self.pos += 1
                key = self.text[start:self.pos]
            else:
                raise ValueError("Expected object key")

            self.skip_ws_and_comments()
            self.expect(':')
            self.skip_ws_and_comments()
            val = self.parse_value()
            obj[key] = val

            self.skip_ws_and_comments()
            if self.peek() == '}':
                self.advance()
                return obj
            elif self.peek() == ',':
                self.advance()
                self.skip_ws_and_comments()
                if self.peek() == '}':
                    self.advance()
                    return obj
            else:
                raise ValueError("Expected ',' or '}' in object")

    def parse_array(self):
        self.expect('[')
        arr = []
        self.skip_ws_and_comments()
        if self.peek() == ']':
            self.advance()
            return arr

        while True:
            self.skip_ws_and_comments()
            val = self.parse_value()
            arr.append(val)

            self.skip_ws_and_comments()
            if self.peek() == ']':
                self.advance()
                return arr
            elif self.peek() == ',':
                self.advance()
                self.skip_ws_and_comments()
                if self.peek() == ']':
                    self.advance()
                    return arr
            else:
                raise ValueError("Expected ',' or ']' in array")

    def expect(self, ch):
        if self.peek() != ch:
            raise ValueError(f"Expected '{ch}'")
        self.advance()

def parse_relaxed(text: str):
    return _Parser(text).parse()

def parse_relaxed(text: str):
    class Parser:
        def __init__(self, text):
            self.text = text
            self.pos = 0
            self.length = len(text)

        def parse(self):
            self.skip_ws()
            if self.pos >= self.length:
                raise ValueError("Empty input")
            val = self.parse_value()
            self.skip_ws()
            if self.pos < self.length:
                raise ValueError("Trailing non-whitespace after top-level value")
            return val

        def skip_ws(self):
            while self.pos < self.length:
                ch = self.text[self.pos]
                if ch in ' \t\n\r':
                    self.pos += 1
                elif ch == '/' and self.pos + 1 < self.length and self.text[self.pos+1] == '/':
                    self.pos += 2
                    while self.pos < self.length and self.text[self.pos] != '\n':
                        self.pos += 1
                    if self.pos < self.length:
                        self.pos += 1
                elif ch == '/' and self.pos + 1 < self.length and self.text[self.pos+1] == '*':
                    self.pos += 2
                    while self.pos < self.length:
                        if self.text[self.pos] == '*' and self.pos + 1 < self.length and self.text[self.pos+1] == '/':
                            self.pos += 2
                            break
                        self.pos += 1
                    else:
                        raise ValueError("Unterminated block comment")
                else:
                    break

        def parse_value(self):
            self.skip_ws()
            if self.pos >= self.length:
                return None
            ch = self.text[self.pos]
            if ch == '{':
                return self.parse_object()
            elif ch == '[':
                return self.parse_array()
            elif ch == '"':
                return self.parse_string(True)
            elif ch == "'":
                return self.parse_string(False)
            elif ch == 't':
                return self.parse_literal("true", True)
            elif ch == 'f':
                return self.parse_literal("false", False)
            elif ch == 'n':
                return self.parse_literal("null", None)
            elif ch == '-' or ch.isdigit():
                return self.parse_number()
            else:
                raise ValueError(f"Unexpected character: {ch!r}")

        def parse_literal(self, expected, value):
            if self.text[self.pos:self.pos+len(expected)] == expected:
                end = self.pos + len(expected)
                if end < self.length and (self.text[end].isalnum() or self.text[end] == '_'):
                    raise ValueError(f"Unexpected literal")
                self.pos = end
                return value
            raise ValueError(f"Unexpected literal")

        def parse_object(self):
            self.pos += 1
            obj = {}
            self.skip_ws()
            if self.pos < self.length and self.text[self.pos] == '}':
                self.pos += 1
                return obj
            while True:
                self.skip_ws()
                key = self.parse_key()
                self.skip_ws()
                if self.pos >= self.length or self.text[self.pos] != ':':
                    raise ValueError("Expected ':' after object key")
                self.pos += 1
                self.skip_ws()
                val = self.parse_value()
                obj[key] = val
                self.skip_ws()
                if self.pos < self.length and self.text[self.pos] == ',':
                    self.pos += 1
                    self.skip_ws()
                    if self.pos < self.length and self.text[self.pos] == '}':
                        break
                    continue
                elif self.pos < self.length and self.text[self.pos] == '}':
                    self.pos += 1
                    return obj
                else:
                    raise ValueError("Expected ',' or '}' in object")

        def parse_key(self):
            self.skip_ws()
            if self.pos < self.length and self.text[self.pos] == '"':
                return self.parse_string(True)
            elif self.pos < self.length and self.text[self.pos] == "'":
                return self.parse_string(False)
            elif self.pos < self.length and (self.text[self.pos].isalpha() or self.text[self.pos] == '_'):
                start = self.pos
                while self.pos < self.length and (self.text[self.pos].isalnum() or self.text[self.pos] == '_'):
                    self.pos += 1
                return self.text[start:self.pos]
            else:
                raise ValueError("Expected object key")

        def parse_array(self):
            self.pos += 1
            arr = []
            self.skip_ws()
            if self.pos < self.length and self.text[self.pos] == ']':
                self.pos += 1
                return arr
            while True:
                self.skip_ws()
                val = self.parse_value()
                arr.append(val)
                self.skip_ws()
                if self.pos < self.length and self.text[self.pos] == ',':
                    self.pos += 1
                    self.skip_ws()
                    if self.pos < self.length and self.text[self.pos] == ']':
                        break
                    continue
                elif self.pos < self.length and self.text[self.pos] == ']':
                    self.pos += 1
                    return arr
                else:
                    raise ValueError("Expected ',' or ']' in array")

        def parse_string(self, dq=True):
            quote = '"' if dq else "'"
            self.pos += 1
            chars = []
            while self.pos < self.length:
                ch = self.text[self.pos]
                if ch == quote:
                    self.pos += 1
                    return ''.join(chars)
                elif ch == '\\':
                    self.pos += 1
                    if self.pos >= self.length:
                        raise ValueError("Unterminated string escape")
                    esc = self.text[self.pos]
                    self.pos += 1
                    if esc == '"':
                        chars.append('"')
                    elif esc == "'":
                        chars.append("'")
                    elif esc == '\\':
                        chars.append('\\')
                    elif esc == '/':
                        chars.append('/')
                    elif esc == 'b':
                        chars.append('\b')
                    elif esc == 'f':
                        chars.append('\f')
                    elif esc == 'n':
                        chars.append('\n')
                    elif esc == 'r':
                        chars.append('\r')
                    elif esc == 't':
                        chars.append('\t')
                    elif esc == 'u':
                        if self.pos + 4 > self.length:
                            raise ValueError("Invalid unicode escape")
                        hex_str = self.text[self.pos:self.pos+4]
                        self.pos += 4
                        chars.append(chr(int(hex_str, 16)))
                    else:
                        raise ValueError(f"Invalid escape character: {esc!r}")
                else:
                    chars.append(ch)
                    self.pos += 1
            raise ValueError("Unterminated string")

        def parse_number(self):
            start = self.pos
            if self.text[self.pos] == '-':
                self.pos += 1
            if self.pos >= self.length or not self.text[self.pos].isdigit():
                raise ValueError("Invalid number")
            while self.pos < self.length and self.text[self.pos].isdigit():
                self.pos += 1
            if self.pos < self.length and self.text[self.pos] == '.':
                self.pos += 1
                if self.pos >= self.length or not self.text[self.pos].isdigit():
                    raise ValueError("Invalid number")
                while self.pos < self.length and self.text[self.pos].isdigit():
                    self.pos += 1
            if self.pos < self.length and self.text[self.pos] in 'eE':
                self.pos += 1
                if self.pos < self.length and self.text[self.pos] in '+-':
                    self.pos += 1
                if self.pos >= self.length or not self.text[self.pos].isdigit():
                    raise ValueError("Invalid number")
                while self.pos < self.length and self.text[self.pos].isdigit():
                    self.pos += 1
            num_str = self.text[start:self.pos]
            if '.' in num_str or 'e' in num_str or 'E' in num_str:
                return float(num_str)
            else:
                return int(num_str)

    return Parser(text).parse()

def topo_batches(deps: dict[str, list[str]]) -> list[list[str]]:
    all_nodes = set(deps.keys())
    for prereqs in deps.values():
        all_nodes.update(prereqs)

    graph = {node: [] for node in all_nodes}
    in_degree = {node: 0 for node in all_nodes}

    for node, prereqs in deps.items():
        for prereq in prereqs:
            graph[prereq].append(node)
            in_degree[node] += 1

    q = [node for node in all_nodes if in_degree[node] == 0]

    result = []
    processed_count = 0

    while q:
        batch = sorted(q)
        result.append(batch)
        processed_count += len(batch)

        next_q = []
        for u in q:
            for v in graph[u]:
                in_degree[v] -= 1
                if in_degree[v] == 0:
                    next_q.append(v)
        q = next_q

    if processed_count != len(all_nodes):
        raise ValueError("Cycle detected")

    return result

def topo_batches(deps: dict[str, list[str]]) -> list[list[str]]:
    all_nodes = set(deps.keys())
    for prereqs in deps.values():
        all_nodes.update(prereqs)

    adj = {node: set() for node in all_nodes}
    in_degree = {node: 0 for node in all_nodes}

    for u, prereqs in deps.items():
        for v in set(prereqs):
            adj[v].add(u)
            in_degree[u] += 1

    queue = [node for node in all_nodes if in_degree[node] == 0]
    result = []
    processed_count = 0

    while queue:
        batch = sorted(queue)
        result.append(batch)
        processed_count += len(batch)

        next_queue = []
        for u in batch:
            for v in adj[u]:
                in_degree[v] -= 1
                if in_degree[v] == 0:
                    next_queue.append(v)
        queue = next_queue

    if processed_count != len(all_nodes):
        raise ValueError("Cycle detected in dependencies")

    return result

def wrap_text(words: list[str], width: int) -> list[str]:
    n = len(words)
    dp = [float('inf')] * (n + 1)
    dp[n] = 0
    choice = [0] * n

    for i in range(n - 1, -1, -1):
        if len(words[i]) > width:
            dp[i] = dp[i+1]
            choice[i] = i + 1
            continue

        current_len = 0
        for j in range(i + 1, n + 1):
            current_len += len(words[j-1])
            line_len = current_len + (j - i - 1)
            if line_len > width:
                break

            if dp[j] == float('inf'):
                continue

            cost = (width - line_len)**2 if j < n else 0
            total = cost + dp[j]

            if total < dp[i]:
                dp[i] = total
                choice[i] = j
            elif total == dp[i]:
                if j > choice[i]:
                    choice[i] = j

    lines = []
    i = 0
    while i < n:
        j = choice[i]
        lines.append(" ".join(words[i:j]))
        i = j

    return lines

def unify(t1, t2) -> dict | None:
    def apply_sub(term, theta):
        if term[0] == 'var':
            name = term[1]
            if name in theta:
                return apply_sub(theta[name], theta)
            return term
        else:
            functor = term[0]
            new_args = tuple(apply_sub(arg, theta) for arg in term[1:])
            return (functor, *new_args)

    def occurs(var_name, term):
        if term[0] == 'var':
            return term[1] == var_name
        return any(occurs(var_name, arg) for arg in term[1:])

    def unify_rec(t1, t2, theta):
        t1 = apply_sub(t1, theta)
        t2 = apply_sub(t2, theta)

        if t1[0] == 'var' and t2[0] == 'var':
            if t1[1] == t2[1]:
                return theta
            else:
                theta[t1[1]] = t2
                for k in list(theta.keys()):
                    theta[k] = apply_sub(theta[k], theta)
                return theta
        elif t1[0] == 'var':
            if occurs(t1[1], t2):
                return None
            theta[t1[1]] = t2
            for k in list(theta.keys()):
                theta[k] = apply_sub(theta[k], theta)
            return theta
        elif t2[0] == 'var':
            return unify_rec(t2, t1, theta)
        else:
            if t1[0] != t2[0] or len(t1) != len(t2):
                return None
            for a1, a2 in zip(t1[1:], t2[1:]):
                res = unify_rec(a1, a2, theta)
                if res is None:
                    return None
                theta = res
            return theta

    result = unify_rec(t1, t2, {})
    if result is None:
        return None

    # Ensure fully resolved
    for k in list(result.keys()):
        result[k] = apply_sub(result[k], result)

    return result

def unify(t1, t2):
    def is_var(t):
        return isinstance(t, tuple) and len(t) == 2 and t[0] == 'var'

    def is_compound(t):
        return isinstance(t, tuple) and len(t) >= 1 and t[0] != 'var'

    def apply_subst(term, subst):
        if is_var(term):
            name = term[1]
            if name in subst:
                return apply_subst(subst[name], subst)
            return term
        if is_compound(term):
            return (term[0],) + tuple(apply_subst(arg, subst) for arg in term[1:])
        return term

    def occurs_in(var, term):
        if is_var(term):
            return var[1] == term[1]
        if is_compound(term):
            return any(occurs_in(var, arg) for arg in term[1:])
        return False

    def resolve_subst(subst):
        resolved = {}
        for var, term in subst.items():
            resolved[var] = apply_subst(term, subst)
        return resolved

    def _unify(t1, t2, subst):
        t1 = apply_subst(t1, subst)
        t2 = apply_subst(t2, subst)

        if t1 == t2:
            return subst
        if is_var(t1):
            if occurs_in(t1, t2):
                return None
            subst[t1[1]] = apply_subst(t2, subst)
            return subst
        if is_var(t2):
            if occurs_in(t2, t1):
                return None
            subst[t2[1]] = apply_subst(t1, subst)
            return subst
        if is_compound(t1) and is_compound(t2):
            if t1[0] != t2[0] or len(t1) != len(t2):
                return None
            for a1, a2 in zip(t1[1:], t2[1:]):
                subst = _unify(a1, a2, subst)
                if subst is None:
                    return None
            return subst
        return None

    result = _unify(t1, t2, {})
    if result is None:
        return None
    return resolve_subst(result)

import bisect

class RangeModule:
    def __init__(self):
        self.intervals = []

    def add_range(self, left: int, right: int) -> None:
        if left == right:
            return
        i = bisect.bisect_left(self.intervals, (left,))
        j = bisect.bisect_left(self.intervals, (right,))

        while i > 0 and self.intervals[i-1][1] >= left:
            i -= 1
        while j < len(self.intervals) and self.intervals[j][0] <= right:
            j += 1

        min_start = left
        max_end = right
        for k in range(i, j):
            if self.intervals[k][0] < min_start:
                min_start = self.intervals[k][0]
            if self.intervals[k][1] > max_end:
                max_end = self.intervals[k][1]

        self.intervals[i:j] = [[min_start, max_end]]

    def query_range(self, left: int, right: int) -> bool:
        idx = bisect.bisect_left(self.intervals, (left,))
        if idx > 0 and self.intervals[idx-1][1] >= right:
            return True
        if idx < len(self.intervals) and self.intervals[idx][0] == left and self.intervals[idx][1] >= right:
            return True
        return False

    def remove_range(self, left: int, right: int) -> None:
        if left == right:
            return
        i = bisect.bisect_left(self.intervals, (left,))
        j = bisect.bisect_left(self.intervals, (right,))

        while i > 0 and self.intervals[i-1][1] >= left:
            i -= 1
        while j < len(self.intervals) and self.intervals[j][0] <= right:
            j += 1

        new_intervals = []
        for k in range(i, j):
            s, e = self.intervals[k]
            if s < left:
                new_intervals.append([s, left])
            if e > right:
                new_intervals.append([right, e])
        self.intervals[i:j] = new_intervals

import bisect

class RangeModule:
    def __init__(self):
        self.intervals = []

    def add_range(self, left: int, right: int) -> None:
        idx = bisect.bisect_left(self.intervals, (left, -float('inf')))
        if idx > 0 and self.intervals[idx-1][1] >= left:
            idx -= 1

        new_left = left
        new_right = right

        while idx < len(self.intervals) and self.intervals[idx][0] <= right:
            new_left = min(new_left, self.intervals[idx][0])
            new_right = max(new_right, self.intervals[idx][1])
            idx += 1

        self.intervals[idx:] = [(new_left, new_right)]

    def query_range(self, left: int, right: int) -> bool:
        idx = bisect.bisect_right(self.intervals, (left, float('inf'))) - 1
        if idx < 0:
            return False
        l, r = self.intervals[idx]
        return l <= left and r >= right

    def remove_range(self, left: int, right: int) -> None:
        idx = bisect.bisect_left(self.intervals, (left, -float('inf')))
        if idx > 0 and self.intervals[idx-1][1] >= left:
            idx -= 1

        new_intervals = []
        while idx < len(self.intervals) and self.intervals[idx][0] < right:
            l, r = self.intervals[idx]
            if l < left:
                new_intervals.append((l, left))
            if r > right:
                new_intervals.append((right, r))
            idx += 1

        self.intervals[idx-len(new_intervals):idx] = new_intervals

import datetime

def next_run(expr: str, after: datetime.datetime) -> datetime.datetime:
    def parse_field(s, min_val, max_val):
        values = set()
        for part in s.split(','):
            if '/' in part:
                base, step = part.split('/')
                step = int(step)
                if base == '*':
                    start, end = min_val, max_val
                elif '-' in base:
                    start, end = map(int, base.split('-'))
                else:
                    start, end = int(base), max_val
                for i in range(start, end + 1, step):
                    values.add(i)
            elif '-' in part:
                start, end = map(int, part.split('-'))
                for i in range(start, end + 1):
                    values.add(i)
            elif part == '*':
                for i in range(min_val, max_val + 1):
                    values.add(i)
            else:
                values.add(int(part))
        return values

    fields = expr.split()
    if len(fields) != 5:
        raise ValueError("Invalid cron expression")

    minute_vals = parse_field(fields[0], 0, 59)
    hour_vals = parse_field(fields[1], 0, 23)
    dom_vals = parse_field(fields[2], 1, 31)
    month_vals = parse_field(fields[3], 1, 12)
    dow_vals = parse_field(fields[4], 0, 6)

    dom_unrestricted = dom_vals == set(range(1, 32))
    dow_unrestricted = dow_vals == set(range(0, 7))

    dt = after.replace(second=0, microsecond=0)
    if dt <= after:
        dt += datetime.timedelta(minutes=1)

    while True:
        if dt.month not in month_vals:
            valid_months = sorted(month_vals)
            found = False
            for m in valid_months:
                if m > dt.month:
                    dt = dt.replace(month=m, day=1, hour=0, minute=0, second=0, microsecond=0)
                    found = True
                    break
            if not found:
                dt = dt.replace(year=dt.year + 1, month=valid_months[0], day=1, hour=0, minute=0, second=0, microsecond=0)
            continue

        if dt.hour not in hour_vals:
            valid_hours = sorted(hour_vals)
            found = False
            for h in valid_hours:
                if h > dt.hour:
                    dt = dt.replace(hour=h, minute=0, second=0, microsecond=0)
                    found = True
                    break
            if not found:
                dt += datetime.timedelta(days=1)
            continue

        if dt.minute not in minute_vals:
            valid_minutes = sorted(minute_vals)
            found = False
            for m in valid_minutes:
                if m > dt.minute:
                    dt = dt.replace(minute=m, second=0, microsecond=0)
                    found = True
                    break
            if not found:
                dt += datetime.timedelta(hours=1)
            continue

        dom_match = dt.day in dom_vals
        cron_wd = (dt.weekday() + 1) % 7
        dow_match = cron_wd in dow_vals

        if dom_unrestricted or dow_unrestricted:
            day_match = dom_match and dow_match
        else:
            day_match = dom_match or dow_match

        if day_match:
            return dt
        dt += datetime.timedelta(minutes=1)

import datetime

def next_run(expr: str, after: datetime.datetime) -> datetime.datetime:
    fields = expr.strip().split()
    if len(fields) != 5:
        raise ValueError("Cron expression must have 5 fields")

    def parse_field(f, min_v, max_v):
        is_star = (f == '*')
        vals = set()
        for part in f.split(','):
            if '/' in part:
                base, step = part.split('/', 1)
                if base == '*':
                    start, end = min_v, max_v
                elif '-' in base:
                    s, e = map(int, base.split('-', 1))
                    start, end = s, e
                else:
                    start, end = int(base), max_v
                vals.update(range(start, end + 1, int(step)))
            elif '-' in part:
                s, e = map(int, part.split('-', 1))
                vals.update(range(s, e + 1))
            elif part == '*':
                vals.update(range(min_v, max_v + 1))
            else:
                vals.add(int(part))
        return sorted(vals), is_star

    minutes, _ = parse_field(fields[0], 0, 59)
    hours, _ = parse_field(fields[1], 0, 23)
    doms, dom_star = parse_field(fields[2], 1, 31)
    months, _ = parse_field(fields[3], 1, 12)
    dows, dow_star = parse_field(fields[4], 0, 6)

    months_set = set(months)
    minutes_set = set(minutes)
    hours_set = set(hours)
    doms_set = set(doms)
    dows_set = set(dows)

    dt = after.replace(second=0, microsecond=0)
    if dt <= after:
        dt += datetime.timedelta(minutes=1)

    while True:
        if dt.month not in months_set:
            next_m = None
            for m in months:
                if m > dt.month:
                    next_m = m
                    break
            if next_m is not None:
                dt = dt.replace(month=next_m, day=1, hour=0, minute=0)
            else:
                dt = dt.replace(year=dt.year + 1, month=months[0], day=1, hour=0, minute=0)
            continue

        python_dow = dt.weekday()
        cron_dow = (python_dow + 1) % 7
        if dom_star and dow_star:
            day_match = True
        elif dom_star:
            day_match = (cron_dow in dows_set)
        elif dow_star:
            day_match = (dt.day in doms_set)
        else:
            day_match = (dt.day in doms_set) or (cron_dow in dows_set)

        if not day_match:
            dt += datetime.timedelta(days=1)
            dt = dt.replace(hour=0, minute=0)
            continue

        if dt.hour not in hours_set:
            next_h = None
            for h in hours:
                if h > dt.hour:
                    next_h = h
                    break
            if next_h is not None:
                dt = dt.replace(hour=next_h, minute=0)
            else:
                dt += datetime.timedelta(days=1)
                dt = dt.replace(hour=hours[0], minute=0)
            continue

        if dt.minute not in minutes_set:
            next_min = None
            for m in minutes:
                if m > dt.minute:
                    next_min = m
                    break
            if next_min is not None:
                dt = dt.replace(minute=next_min)
            else:
                dt += datetime.timedelta(hours=1)
                dt = dt.replace(minute=minutes[0])
            continue

        return dt

def divmod_str(a: str, b: str) -> tuple[str, str]:
    if not b or b.lstrip('0') == '':
        raise ZeroDivisionError("division by zero")

    a = a.lstrip('0') or '0'
    b = b.lstrip('0') or '0'

    if a == '0':
        return ('0', '0')

    a_digits = [int(c) for c in a]
    b_digits = [int(c) for c in b]
    m = len(a_digits)

    def compare(A, B):
        if len(A) > len(B): return 1
        if len(A) < len(B): return -1
        for x, y in zip(A, B):
            if x > y: return 1
            if x < y: return -1
        return 0

    def multiply_digit(digits, k):
        res = []
        carry = 0
        for d in reversed(digits):
            prod = d * k + carry
            res.append(prod % 10)
            carry = prod // 10
        while carry:
            res.append(carry % 10)
            carry //= 10
        return res[::-1]

    def subtract(A, B):
        res = []
        borrow = 0
        for i in range(len(A)):
            d1 = A[i] - borrow
            d2 = B[i] if i < len(B) else 0
            if d1 < d2:
                d1 += 10
                borrow = 1
            else:
                borrow = 0
            res.append(d1 - d2)
        return res

    current = []
    quotient_digits = []

    for i in range(m):
        current.append(a_digits[i])
        while len(current) > 1 and current[0] == 0:
            current.pop(0)

        if compare(current, b_digits) >= 0:
            d = 9
            while compare(multiply_digit(b_digits, d), current) > 0:
                d -= 1
            quotient_digits.append(d)
            current = subtract(current, multiply_digit(b_digits, d))
        else:
            quotient_digits.append(0)

    while len(quotient_digits) > 1 and quotient_digits[0] == 0:
        quotient_digits.pop(0)

    while len(current) > 1 and current[0] == 0:
        current.pop(0)

    return (''.join(map(str, quotient_digits)), ''.join(map(str, current)))

def divmod_str(a: str, b: str) -> tuple[str, str]:
    a = a.lstrip('0') or '0'
    b = b.lstrip('0') or '0'

    if b == "0":
        raise ZeroDivisionError("division by zero")
    if a == '0':
        return ("0", "0")

    def less_than(s1, s2):
        if len(s1) < len(s2): return True
        if len(s1) > len(s2): return False
        return s1 < s2

    if less_than(a, b):
        return ("0", a)

    quotient_digits = []
    remainder = ""

    for digit in a:
        remainder += digit
        remainder = remainder.lstrip('0') or '0'

        q = 0
        while not less_than(remainder, b):
            i, j = len(remainder) - 1, len(b) - 1
            borrow = 0
            new_rem = []
            while i >= 0 or j >= 0:
                d1 = int(remainder[i]) - borrow
                d2 = int(b[j]) if j >= 0 else 0
                if d1 < d2:
                    d1 += 10
                    borrow = 1
                else:
                    borrow = 0
                new_rem.append(str(d1 - d2))
                i -= 1
                j -= 1
            remainder = ''.join(reversed(new_rem)).lstrip('0') or '0'
            q += 1

        quotient_digits.append(str(q))

    quotient = ''.join(quotient_digits).lstrip('0') or '0'
    return (quotient, remainder)

class TxDict:
    _DELETED = object()

    def __init__(self, *args, **kwargs):
        self._base = dict(*args, **kwargs)
        self._stack = []

    def __setitem__(self, key, value):
        if self._stack:
            self._stack[-1][key] = value
        else:
            self._base[key] = value

    def __delitem__(self, key):
        if self._stack:
            if not self._contains_check(key):
                raise KeyError(key)
            self._stack[-1][key] = self._DELETED
        else:
            if key not in self._base:
                raise KeyError(key)
            del self._base[key]

    def _contains_check(self, key):
        for txn in reversed(self._stack):
            if key in txn:
                return txn[key] is not self._DELETED
        return key in self._base

    def __getitem__(self, key):
        for txn in reversed(self._stack):
            if key in txn:
                val = txn[key]
                if val is self._DELETED:
                    raise KeyError(key)
                return val
        if key in self._base:
            return self._base[key]
        raise KeyError(key)

    def __contains__(self, key):
        return self._contains_check(key)

    def __len__(self):
        keys = set(self._base.keys())
        for txn in self._stack:
            for k, v in txn.items():
                if v is self._DELETED:
                    keys.discard(k)
                else:
                    keys.add(k)
        return len(keys)

    def __iter__(self):
        seen = set()
        order = []
        for k in self._base:
            if k not in seen:
                seen.add(k)
                order.append(k)
        for txn in self._stack:
            for k, v in txn.items():
                if v is not self._DELETED and k not in seen:
                    seen.add(k)
                    order.append(k)
        yield from order

    def get(self, key, default=None):
        try:
            return self[key]
        except KeyError:
            return default

    def begin(self):
        self._stack.append({})

    def commit(self):
        if not self._stack:
            raise RuntimeError("No active transaction")
        if len(self._stack) == 1:
            txn = self._stack.pop()
            for k, v in txn.items():
                if v is self._DELETED:
                    self._base.pop(k, None)
                else:
                    self._base[k] = v
        else:
            inner = self._stack.pop()
            outer = self._stack[-1]
            for k, v in inner.items():
                outer[k] = v

    def rollback(self):
        if not self._stack:
            raise RuntimeError("No active transaction")
        self._stack.pop()

    def transaction(self):
        class _TxnContext:
            def __init__(self, d):
                self._d = d
            def __enter__(self):
                self._d.begin()
                return self._d
            def __exit__(self, exc_type, exc_val, exc_tb):
                if exc_type is None:
                    self._d.commit()
                else:
                    self._d.rollback()
                    return False
        return _TxnContext(self)

class TxDict:
    def __init__(self, *args, **kwargs):
        self._data = dict(*args, **kwargs)
        self._stack = []

    def begin(self):
        self._stack.append({})

    def commit(self):
        if not self._stack:
            raise RuntimeError("No active transaction")
        changes = self._stack.pop()
        if self._stack:
            self._stack[-1].update(changes)
        else:
            for k, v in changes.items():
                if v is None:
                    self._data.pop(k, None)
                else:
                    self._data[k] = v

    def rollback(self):
        if not self._stack:
            raise RuntimeError("No active transaction")
        self._stack.pop()

    def __setitem__(self, key, value):
        if self._stack:
            self._stack[-1][key] = value
        else:
            self._data[key] = value

    def __delitem__(self, key):
        if key in self:
            if self._stack:
                self._stack[-1][key] = None
            else:
                del self._data[key]
        else:
            raise KeyError(key)

    def __getitem__(self, key):
        for changes in reversed(self._stack):
            if key in changes:
                val = changes[key]
                if val is None:
                    raise KeyError(key)
                return val
        return self._data[key]

    def __contains__(self, key):
        for changes in reversed(self._stack):
            if key in changes:
                return changes[key] is not None
        return key in self._data

    def __len__(self):
        keys = set(self._data)
        for changes in self._stack:
            for k, v in changes.items():
                if v is None:
                    keys.discard(k)
                else:
                    keys.add(k)
        return len(keys)

    def __iter__(self):
        seen = set()
        for k in self._data:
            if k not in seen:
                deleted = True
                for changes in reversed(self._stack):
                    if k in changes:
                        deleted = changes[k] is None
                        break
                if not deleted:
                    seen.add(k)
                    yield k
        for changes in self._stack:
            for k, v in changes.items():
                if v is not None and k not in seen:
                    seen.add(k)
                    yield k

    def get(self, key, default=None):
        try:
            return self[key]
        except KeyError:
            return default

    def transaction(self):
        class _TxContext:
            def __init__(self, tx_dict):
                self.tx_dict = tx_dict

            def __enter__(self):
                self.tx_dict.begin()
                return self.tx_dict

            def __exit__(self, exc_type, exc_val, exc_tb):
                if exc_type is None:
                    self.tx_dict.commit()
                else:
                    self.tx_dict.rollback()
                return False

        return _TxContext(self)

def run_query(sql: str, rows: list[dict]) -> list[dict]:
    def tokenize(sql_str):
        tokens = []
        keywords = {'SELECT', 'FROM', 'WHERE', 'ORDER', 'BY', 'ASC', 'DESC', 'LIMIT', 'AS', 'AND', 'OR'}
        i = 0
        n = len(sql_str)
        while i < n:
            if sql_str[i].isspace():
                i += 1
                continue
            if sql_str[i] == "'":
                j = i + 1
                while j < n and sql_str[j] != "'":
                    j += 1
                if j >= n:
                    raise ValueError("Unterminated string")
                tokens.append(('STRING', sql_str[i+1:j]))
                i = j + 1
                continue
            if sql_str[i].isdigit() or (sql_str[i] == '.' and i+1 < n and sql_str[i+1].isdigit()):
                j = i
                while j < n and (sql_str[j].isdigit() or sql_str[j] == '.'):
                    j += 1
                val = sql_str[i:j]
                tokens.append(('NUMBER', float(val) if '.' in val else int(val)))
                i = j
                continue
            if sql_str[i].isalpha() or sql_str[i] == '_':
                j = i
                while j < n and (sql_str[j].isalnum() or sql_str[j] == '_'):
                    j += 1
                word = sql_str[i:j]
                if word.upper() in keywords:
                    tokens.append(('KEYWORD', word.upper()))
                else:
                    tokens.append(('IDENTIFIER', word))
                i = j
                continue
            if sql_str[i] in '<>=!':
                j = i
                while j < n and sql_str[j] in '<>=!':
                    j += 1
                tokens.append(('OPERATOR', sql_str[i:j]))
                i = j
                continue
            if sql_str[i] == ',':
                tokens.append(('COMMA', ','))
                i += 1
                continue
            if sql_str[i] == '(':
                tokens.append(('LPAREN', '('))
                i += 1
                continue
            if sql_str[i] == ')':
                tokens.append(('RPAREN', ')'))
                i += 1
                continue
            raise ValueError(f"Unexpected character: {sql_str[i]}")
        return tokens

    class Parser:
        def __init__(self, tokens):
            self.tokens = tokens
            self.pos = 0

        def peek(self):
            if self.pos < len(self.tokens):
                return self.tokens[self.pos]
            return None

        def consume(self, expected_type=None):
            token = self.peek()
            if token is None:
                raise ValueError("Unexpected end of input")
            if expected_type and token[0] != expected_type:
                raise ValueError(f"Expected {expected_type}, got {token[0]}: {token[1]}")
            self.pos += 1
            return token

        def parse(self):
            self.consume('KEYWORD', 'SELECT')
            columns = self.parse_columns()
            self.consume('KEYWORD', 'FROM')
            self.consume('IDENTIFIER') # table name, ignored

            where_cond = None
            if self.peek() and self.peek()[1] == 'WHERE':
                self.consume()
                where_cond = self.parse_condition()

            order_by = None
            if self.peek() and self.peek()[1] == 'ORDER':
                self.consume()
                self.consume('KEYWORD', 'BY')
                order_by = self.parse_order_list()

            limit = None
            if self.peek() and self.peek()[1] == 'LIMIT':
                self.consume()
                token = self.consume('NUMBER')
                limit = token[1]

            if self.pos < len(self.tokens):
                raise ValueError("Unexpected tokens after query")

            return columns, where_cond, order_by, limit

        def parse_columns(self):
            if self.peek() and self.peek()[1] == '*':
                self.consume()
                return [('star', '*')]
            cols = [self.parse_column_expr()]
            while self.peek() and self.peek()[0] == 'COMMA':
                self.consume()
                cols.append(self.parse_column_expr())
            return cols

        def parse_column_expr(self):
            token = self.consume('IDENTIFIER')
            name = token[1]
            alias = name
            if self.peek() and self.peek()[1] == 'AS':
                self.consume()
                alias = self.consume('IDENTIFIER')[1]
            return (name, alias)

        def parse_condition(self):
            return self.parse_or()

        def parse_or(self):
            left = self.parse_and()
            while self.peek() and self.peek()[1] == 'OR':
                self.consume()
                right = self.parse_and()
                left = ('OR', left, right)
            return left

        def parse_and(self):
            left = self.parse_comparison()
            while self.peek() and self.peek()[1] == 'AND':
                self.consume()
                right = self.parse_comparison()
                left = ('AND', left, right)
            return left

        def parse_comparison(self):
            left = self.parse_atom()
            if self.peek() and self.peek()[0] == 'OPERATOR':
                op = self.consume()[1]
                right = self.parse_atom()
                return ('CMP', left, op, right)
            return left

        def parse_atom(self):
            token = self.peek()
            if token[0] == 'IDENTIFIER':
                self.consume()
                return ('IDENTIFIER', token[1])
            elif token[0] == 'NUMBER':
                self.consume()
                return ('NUMBER', token[1])
            elif token[0] == 'STRING':
                self.consume()
                return ('STRING', token[1])
            elif token[0] == 'LPAREN':
                self.consume()
                cond = self.parse_condition()
                self.consume('RPAREN')
                return cond
            raise ValueError("Expected atom in condition")

        def parse_order_list(self):
            order = [self.parse_order_item()]
            while self.peek() and self.peek()[0] == 'COMMA':
                self.consume()
                order.append(self.parse_order_item())
            return order

        def parse_order_item(self):
            col = self.consume('IDENTIFIER')[1]
            direction = 'ASC'
            if self.peek() and self.peek()[0] == 'KEYWORD' and self.peek()[1] in ('ASC', 'DESC'):
                direction = self.consume()[1]
            return (col, direction)

    tokens = tokenize(sql)
    parser = Parser(tokens)
    columns, where_cond, order_by, limit = parser.parse()

    def get_value(atom, row):
        if atom[0] == 'IDENTIFIER':
            if atom[1] not in row:
                raise ValueError(f"Column {atom[1]} not found in row")
            return row[atom[1]]
        elif atom[0] == 'NUMBER':
            return atom[1]
        elif atom[0] == 'STRING':
            return atom[1]
        raise ValueError(f"Unknown atom type: {atom[0]}")

    def evaluate_condition(cond, row):
        if cond[0] == 'AND':
            return evaluate_condition(cond[1], row) and evaluate_condition(cond[2], row)
        elif cond[0] == 'OR':
            return evaluate_condition(cond[1], row) or evaluate_condition(cond[2], row)
        elif cond[0] == 'CMP':
            left_val = get_value(cond[1], row)
            right_val = get_value(cond[2], row)
            op = cond[3]
            if op == '=': return left_val == right_val
            if op == '!=': return left_val != right_val
            if op == '<': return left_val < right_val
            if op == '<=': return left_val <= right_val
            if op == '>': return left_val > right_val
            if op == '>=': return left_val >= right_val
        raise ValueError(f"Unknown condition type: {cond[0]}")

    if where_cond:
        rows = [r for r in rows if evaluate_condition(where_cond, r)]

    if order_by:
        for col, direction in reversed(order_by):
            reverse = (direction == 'DESC')
            rows.sort(key=lambda r, c=col: r.get(c, 0), reverse=reverse)

    if limit is not None:
        rows = rows[:int(limit)]

    result = []
    for row in rows:
        new_row = {}
        if columns and columns[0][0] == '*':
            new_row.update(row)
        else:
            for name, alias in columns:
                if name in row:
                    new_row[alias] = row[name]
        result.append(new_row)

    return result

import re

def run_query(sql: str, rows: list[dict]) -> list[dict]:
    tokens = []
    keywords = {'SELECT', 'FROM', 'WHERE', 'ORDER', 'BY', 'ASC', 'DESC', 'LIMIT', 'AS', 'AND', 'OR'}
    pattern = r"\b(SELECT|FROM|WHERE|ORDER|BY|ASC|DESC|LIMIT|AS|AND|OR)\b|[=<>!]+|[0-9]+(?:\.[0-9]+)?|'[^']*'|[a-zA-Z_][a-zA-Z0-9_]*|\*|,|\(|\)"
    for m in re.finditer(pattern, sql):
        t = m.group(0)
        if t.upper() in keywords:
            tokens.append(('KEYWORD', t.upper()))
        elif re.match(r'^[=<>!]+$', t):
            tokens.append(('OP', t))
        elif re.match(r'^[0-9]+(?:\.[0-9]+)?$', t):
            tokens.append(('NUMBER', float(t) if '.' in t else int(t)))
        elif t.startswith("'"):
            tokens.append(('STRING', t[1:-1]))
        elif t == '*':
            tokens.append(('STAR', '*'))
        elif t == ',':
            tokens.append(('COMMA', ','))
        elif t == '(':
            tokens.append(('LPAREN', '('))
        elif t == ')':
            tokens.append(('RPAREN', ')'))
        else:
            tokens.append(('ID', t))
    tokens.append(('EOF', None))

    class Parser:
        def __init__(self, tokens):
            self.tokens = tokens
            self.pos = 0
        def peek(self):
            return self.tokens[self.pos] if self.pos < len(self.tokens) else ('EOF', None)
        def advance(self):
            tok = self.tokens[self.pos]
            self.pos += 1
            return tok
        def expect(self, ttype, tval=None):
            tok = self.advance()
            if tok[0] != ttype or (tval is not None and tok[1] != tval):
                raise ValueError(f"Parse error: expected {ttype} {tval}, got {tok}")
            return tok
        def parse(self):
            self.expect('KEYWORD', 'SELECT')
            select_list = self.parse_select_list()
            self.expect('KEYWORD', 'FROM')
            self.advance() # skip table name
            where_clause = None
            if self.peek()[0] == 'KEYWORD' and self.peek()[1] == 'WHERE':
                self.advance()
                where_clause = self.parse_condition()
            order_by = []
            if self.peek()[0] == 'KEYWORD' and self.peek()[1] == 'ORDER':
                self.advance()
                self.expect('KEYWORD', 'BY')
                order_by = self.parse_order_list()
            limit = None
            if self.peek()[0] == 'KEYWORD' and self.peek()[1] == 'LIMIT':
                self.advance()
                tok = self.expect('NUMBER')
                limit = int(tok[1])
            self.expect('EOF')
            return select_list, where_clause, order_by, limit

        def parse_select_list(self):
            items = []
            if self.peek()[0] == 'STAR':
                self.advance()
                items.append(('*', None))
            else:
                items.append(self.parse_select_item())
                while self.peek()[0] == 'COMMA':
                    self.advance()
                    items.append(self.parse_select_item())
            return items

        def parse_select_item(self):
            tok = self.expect('ID')
            alias = None
            if self.peek()[0] == 'KEYWORD' and self.peek()[1] == 'AS':
                self.advance()
                alias_tok = self.expect('ID')
                alias = alias_tok[1]
            return (tok[1], alias)

        def parse_condition(self):
            return self.parse_or_condition()

        def parse_or_condition(self):
            left = self.parse_and_condition()
            while self.peek()[0] == 'KEYWORD' and self.peek()[1] == 'OR':
                self.advance()
                right = self.parse_and_condition()
                left = ('OR', left, right)
            return left

        def parse_and_condition(self):
            left = self.parse_primary()
            while self.peek()[0] == 'KEYWORD' and self.peek()[1] == 'AND':
                self.advance()
                right = self.parse_primary()
                left = ('AND', left, right)
            return left

        def parse_primary(self):
            if self.peek()[0] == 'LPAREN':
                self.advance()
                cond = self.parse_condition()
                self.expect('RPAREN')
                return cond
            return self.parse_comparison()

        def parse_comparison(self):
            col = self.expect('ID')[1]
            op_tok = self.expect('OP')
            val = self.advance()
            return ('CMP', col, op_tok[1], val[1])

        def parse_order_list(self):
            items = []
            tok = self.expect('ID')
            direction = 'ASC'
            if self.peek()[0] == 'KEYWORD' and self.peek()[1] in ('ASC', 'DESC'):
                direction = self.advance()[1]
            items.append((tok[1], direction))
            while self.peek()[0] == 'COMMA':
                self.advance()
                tok = self.expect('ID')
                direction = 'ASC'
                if self.peek()[0] == 'KEYWORD' and self.peek()[1] in ('ASC', 'DESC'):
                    direction = self.advance()[1]
                items.append((tok[1], direction))
            return items

    parser = Parser(tokens)
    select_list, where_clause, order_by, limit = parser.parse()

    def evaluate_condition(cond, row):
        if cond is None:
            return True
        if cond[0] == 'CMP':
            _, col, op, val = cond
            row_val = row.get(col)
            if row_val is None:
                return False
            if op == '=':
                return row_val == val
            elif op == '!=':
                return row_val != val
            elif op == '<':
                return row_val < val
            elif op == '<=':
                return row_val <= val
            elif op == '>':
                return row_val > val
            elif op == '>=':
                return row_val >= val
        elif cond[0] == 'AND':
            return evaluate_condition(cond[1], row) and evaluate_condition(cond[2], row)
        elif cond[0] == 'OR':
            return evaluate_condition(cond[1], row) or evaluate_condition(cond[2], row)
        return False

    filtered_rows = [row for row in rows if evaluate_condition(where_clause, row)]

    if order_by:
        for col, direction in reversed(order_by):
            reverse_flag = (direction == 'DESC')
            filtered_rows.sort(key=lambda r, c=col: r.get(c), reverse=reverse_flag)

    result = []
    for row in filtered_rows:
        res = {}
        for col, alias in select_list:
            if col == '*':
                res.update(row)
            else:
                key = alias if alias else col
                res[key] = row.get(col)
        result.append(res)

    if limit is not None:
        result = result[:limit]

    return result

import heapq

class MedianStream:
    def __init__(self):
        self.left = []  # max-heap (stores -x)
        self.right = [] # min-heap
        self.removed = {}
        self.left_count = 0
        self.right_count = 0
        self.counts = {}

    def _prune(self, heap):
        while heap:
            val = heap[0]
            if val in self.removed and self.removed[val] > 0:
                heapq.heappop(heap)
                self.removed[val] -= 1
                if self.removed[val] == 0:
                    del self.removed[val]
            else:
                break

    def add(self, x: float) -> None:
        self.counts[x] = self.counts.get(x, 0) + 1
        if not self.left or x <= -self.left[0]:
            heapq.heappush(self.left, -x)
            self.left_count += 1
        else:
            heapq.heappush(self.right, x)
            self.right_count += 1
        self._rebalance()

    def _rebalance(self):
        if self.left_count > self.right_count + 1:
            self._prune(self.left)
            val = -heapq.heappop(self.left)
            self.left_count -= 1
            heapq.heappush(self.right, val)
            self.right_count += 1
        elif self.right_count > self.left_count:
            self._prune(self.right)
            val = heapq.heappop(self.right)
            self.right_count -= 1
            heapq.heappush(self.left, -val)
            self.left_count += 1

    def remove(self, x: float) -> None:
        if self.counts.get(x, 0) == 0:
            raise ValueError(f"{x} not found in stream")

        self.counts[x] -= 1
        self.removed[x] = self.removed.get(x, 0) + 1

        self._prune(self.left)
        if not self.left or x > -self.left[0]:
            self.right_count -= 1
        else:
            self.left_count -= 1

        self._rebalance()

    def median(self) -> float:
        self._prune(self.left)
        self._prune(self.right)

        if self.left_count == 0:
            raise ValueError("Stream is empty")

        if self.left_count > self.right_count:
            return -self.left[0]
        else:
            return (-self.left[0] + self.right[0]) / 2.0

import heapq
from collections import Counter

class MedianStream:
    def __init__(self):
        self.lo = []  # max-heap (stores negated values)
        self.hi = []  # min-heap
        self.lo_size = 0
        self.hi_size = 0
        self.removed = Counter()
        self.counts = Counter()

    def _clean_lo(self):
        while self.lo and self.removed[-self.lo[0]] > 0:
            val = -heapq.heappop(self.lo)
            self.removed[val] -= 1
            self.lo_size -= 1

    def _clean_hi(self):
        while self.hi and self.removed[self.hi[0]] > 0:
            val = heapq.heappop(self.hi)
            self.removed[val] -= 1
            self.hi_size -= 1

    def add(self, x: float) -> None:
        self.counts[x] += 1
        if not self.lo:
            heapq.heappush(self.lo, -x)
            self.lo_size += 1
        else:
            self._clean_lo()
            self._clean_hi()
            if x <= -self.lo[0]:
                heapq.heappush(self.lo, -x)
                self.lo_size += 1
            else:
                heapq.heappush(self.hi, x)
                self.hi_size += 1
        self._rebalance()

    def _rebalance(self):
        if self.lo_size > self.hi_size + 1:
            self._clean_lo()
            val = -heapq.heappop(self.lo)
            self.lo_size -= 1
            heapq.heappush(self.hi, val)
            self.hi_size += 1
        elif self.hi_size > self.lo_size:
            self._clean_hi()
            val = heapq.heappop(self.hi)
            self.hi_size -= 1
            heapq.heappush(self.lo, -val)
            self.lo_size += 1

    def remove(self, x: float) -> None:
        if self.counts[x] == 0:
            raise ValueError("Element not found")
        self.counts[x] -= 1
        self.removed[x] += 1

        self._clean_lo()
        self._clean_hi()

        if self.lo and x <= -self.lo[0]:
            self.lo_size -= 1
        else:
            self.hi_size -= 1

        self._rebalance()

    def median(self) -> float:
        self._clean_lo()
        self._clean_hi()

        if self.lo_size == 0 and self.hi_size == 0:
            return 0.0

        if self.lo_size > self.hi_size:
            return -self.lo[0]
        else:
            return (-self.lo[0] + self.hi[0]) / 2.0
